const path = require('path')

// Helper to load module with mocks
const loadWithMocks = ({ getErrorPluginInfoMock, assignErrorMock }) => {
  jest.resetModules()

  const mainPath = path.resolve(__dirname, '../../../../src/plugins/properties/main.js')
  const infoPath = path.resolve(__dirname, '../../../../src/plugins/info/main.js')
  const assignPath = path.resolve(__dirname, '../../../../src/plugins/properties/assign.js')

  // Provide mocks for the dependencies before requiring the module under test
  jest.doMock(infoPath, () => ({ getErrorPluginInfo: getErrorPluginInfoMock }))
  jest.doMock(assignPath, () => ({ assignError: assignErrorMock }))

  return require(mainPath)
}

describe('applyPluginProperties via setPluginsProperties', () => {
  test('skips plugins without properties()', () => {
    const getErrorPluginInfo = jest.fn()
    const assignError = jest.fn()

    const { setPluginsProperties } = loadWithMocks({
      getErrorPluginInfoMock: getErrorPluginInfo,
      assignErrorMock: assignError,
    })

    const error = { message: 'err' }
    const plugin = { fullName: 'no-props' }
    const plugins = [plugin]

    setPluginsProperties(error, plugins)

    expect(getErrorPluginInfo).not.toHaveBeenCalled()
    expect(assignError).not.toHaveBeenCalled()
  })

  test('calls properties(), validates return and assigns error', () => {
    const getErrorPluginInfo = jest.fn().mockReturnValue({ info: 'ok' })
    const assignError = jest.fn()

    const { setPluginsProperties } = loadWithMocks({
      getErrorPluginInfoMock: getErrorPluginInfo,
      assignErrorMock: assignError,
    })

    const error = { message: 'err' }
    const plugin = {
      fullName: 'with-props',
      properties: jest.fn((info) => ({ fromInfo: info.info })),
    }
    const plugins = [plugin]

    setPluginsProperties(error, plugins)

    expect(getErrorPluginInfo).toHaveBeenCalledWith({ error, plugins, plugin })
    expect(plugin.properties).toHaveBeenCalledWith({ info: 'ok' })
    expect(assignError).toHaveBeenCalledWith(error, { fromInfo: 'ok' }, plugins)
  })

  test('throws TypeError when properties() returns non-plain object', () => {
    const getErrorPluginInfo = jest.fn().mockReturnValue({ info: 'x' })
    const assignError = jest.fn()

    const { setPluginsProperties } = loadWithMocks({
      getErrorPluginInfoMock: getErrorPluginInfo,
      assignErrorMock: assignError,
    })

    const error = { message: 'err' }
    const plugin = {
      fullName: 'bad-props',
      properties: jest.fn(() => null), // null is not a plain object
    }
    const plugins = [plugin]

    expect(() => setPluginsProperties(error, plugins)).toThrow(TypeError)
    try {
      setPluginsProperties(error, plugins)
    } catch (e) {
      expect(e.message).toContain("Plugin \"bad-props\"'s \"properties()\" must return a plain object")
      expect(e.message).toContain('null')
    }

    // assignError must not be called when invalid return
    expect(assignError).not.toHaveBeenCalled()
  })
})
